class Solution {
public:
    int maxDistance(vector<vector<int>>& arrays) {
        int res = 0;
        int minVal = arrays[0].front();
        int maxVal = arrays[0].back();
        for (size_t i = 1; i < arrays.size(); ++i) {
            res = max(res, abs(arrays[i].back() - minVal));
            res = max(res, abs(maxVal - arrays[i].front()));
            minVal = min(minVal, arrays[i].front());
            maxVal = max(maxVal, arrays[i].back());
        }
        return res;
    }
};

class Solution {
    public int maxDistance(List<List<Integer>> arrays) {
        int res = 0;
        int minVal = arrays.get(0).get(0);
        int maxVal = arrays.get(0).get(arrays.get(0).size() - 1);
        for (int i = 1; i < arrays.size(); i++) {
            List<Integer> arr = arrays.get(i);
            int curMin = arr.get(0);
            int curMax = arr.get(arr.size() - 1);
            res = Math.max(res, Math.abs(curMax - minVal));
            res = Math.max(res, Math.abs(maxVal - curMin));
            minVal = Math.min(minVal, curMin);
            maxVal = Math.max(maxVal, curMax);
        }
        return res;
    }
}

